            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "The Theophilanthropists do not call themselves the disciples of such or such a man. They avail themselves of the wise precepts that have been transmitted by writers of all countries and in all ages.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "Religion has two principal enemies, fanaticism and infidelity, or that which is called atheism. The first requires to be combated by reason and morality, the other by natural philosophy.", Author = "Thomas Paine" },
