            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "Search not written or printed books, but the Scripture called the Creation.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "The universe is composed of matter, and, as a system, is sustained by motion.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "All the principles of science are of divine origin. Man cannot make, or invent, or contrive principles; he can only discover them, and he ought to look through the discovery to the Author.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "Instead of looking through the works of creation to the Creator Himself, they stop short and employ the knowledge they acquire to create doubts of His existence. They labor with studied ingenuity to ascribe everything they behold to innate properties of matter and jump over all the rest by saying that matter is eternal.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "When we speak of looking through nature up to nature's God, we speak philosophically the same rational language as when we speak of looking through human laws up to the power that ordained them. God is the power of first cause, nature is the law, and matter is the subject acted upon.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "In things of this kind it sees something which it calls a natural cause, but none of the causes it sees is the cause of that motion which preserves the solar system.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "The atheist who affects to reason, and the fanatic who rejects reason, plunge themselves alike into inextricable difficulties.", Author = "Thomas Paine" },
