            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "I have lived an honest and useful life to mankind; my time has been spend in doing good and I die in perfect composure and resignation to the will of my Creator, God.", Author = "Thomas Paine" },
