            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "All distinctions of nations, and privileges of one above others, are ceased; Christians are taught to account all men their neighbours; and love their neighbours as themselves; and do to all men as they would be done by; to do good to all men; and Man-stealing is ranked with enormous crimes.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "Is the barbarous enslaving our inoffensive neighbours, and treating them like wild beasts subdued by force, reconcilable with all these Divine precepts?", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "To go to nations with whom there is no war, who have no way provoked, without farther design of conquest, purely to catch inoffensive people, like wild beasts, for slaves, is an hight of outrage against Humanity and Justice, that seems left by Heathen nations to be practised by pretended Christians.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "As these people are not convicted of forfeiting freedom, they have still a natural, perfect right to it; and the Governments whenever they come should, in justice set them free, and punish those who hold them in slavery.", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "If the slavery of the parents be unjust, much more is their children's; if the parents were justly slaves, yet the children are born free; this is the natural, perfect right of all mankind; they are nothing but a just recompense to those who bring them up:", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "With what consistency, or decency they complain so loudly of attempts to enslave them, while they hold so many hundred thousands in slavery; and annually enslave many thousands more, without any pretence of authority, or claim upon them?", Author = "Thomas Paine" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Paine", Text = "The past treatment of Africans must naturally fill them with abhorrence of Christians; lead them to think our religion would make them more inhuman savages, if they embraced it; thus the gain of that trade has been pursued in opposition to the Redeemer's cause, and the happiness of men: Are we not, therefore, bound in duty to him and to them to repair these injuries, as far as possible, by taking some proper measures to instruct, not only the slaves here, but the Africans in their own countries?", Author = "Thomas Paine" },
